Linear and XOR rule families gave only chance-level matches, so I am now testing whether any grouping of (a, b) makes the answers purer than shuffled labels do.
```python
import json, numpy as np
rows=[json.loads(l) for l in open('examples.jsonl')]
D={s:np.array([(r['a'],r['b'],r['answer']) for r in rows if r['skill']==s]) for s in range(4)}
rng=np.random.default_rng(0)
def pur(g,y):
    g=np.unique(g,return_inverse=True)[1]
    T=np.zeros((g.max()+1,8),int); np.add.at(T,(g,y),1)
    return T.max(1).sum()
feats={}
a0=np.arange(32)
def gen():
    for m in range(2,33):
        yield f'a%{m}',lambda a,b,m=m:a%m
        yield f'b%{m}',lambda a,b,m=m:b%m
        for n in range(2,33):
            if m*n<=64:
              yield f'(a%{m},b%{n})',lambda a,b,m=m,n=n:(a%m)*100+(b%n)
        for name,f in [('a+b',lambda a,b:a+b),('a-b',lambda a,b:a-b),('a*b',lambda a,b:a*b),('a^b',lambda a,b:a^b),('a&b',lambda a,b:a&b),('a|b',lambda a,b:a|b),('a2+b2',lambda a,b:a*a+b*b),('a2+b',lambda a,b:a*a+b),('a+b2',lambda a,b:a+b*b),('a+2b',lambda a,b:a+2*b),('2a+b',lambda a,b:2*a+b),('a-2b',lambda a,b:a-2*b),('2a-b',lambda a,b:2*a-b),('a+3b',lambda a,b:a+3*b),('3a+b',lambda a,b:3*a+b)]:
            yield f'{name}%{m}',lambda a,b,f=f,m=m:f(a,b)%m
    for k in range(1,5):
        for l in range(1,5):
            yield f'(a>>{k},b>>{l})',lambda a,b,k=k,l=l:(a>>k)*100+(b>>l)
    yield 'min',lambda a,b:np.minimum(a,b)
    yield 'max',lambda a,b:np.maximum(a,b)
    yield 'a<b',lambda a,b:a<b
    yield 'abs',lambda a,b:abs(a-b)
G=list(gen()); print(len(G))
for s in range(4):
    a,b,y=D[s].T
    res=[]
    for name,f in G:
        g=f(a,b)
        p=pur(g,y)
        sh=[pur(g,rng.permutation(y)) for _ in range(12)]
        z=(p-np.mean(sh))/(np.std(sh)+.5)
        res.append((round(float(z),1),name,int(p),round(float(np.mean(sh)),1)))
    print('skill',s,sorted(res,reverse=True)[:7])
