Grouping by a helps in skills 2 and 3 and neighbouring a look alike in skill 0, so I am scanning two-feature rules and if/else rules mod 8, each checked against shuffled labels.
```python
import json, numpy as np, itertools
rows=[json.loads(l) for l in open('examples.jsonl')]
D={s:np.array([(r['a'],r['b'],r['answer']) for r in rows if r['skill']==s]) for s in range(4)}
rng=np.random.default_rng(1)
def fs(a,b):
    return {'a':a,'b':b,'ab':a*b,'x':a^b,'and':a&b,'or':a|b,'a1':a>>1,'b1':b>>1,'a2':a>>2,'b2':b>>2,'a3':a>>3,'b3':b>>3,'aa':a*a,'bb':b*b,'max':np.maximum(a,b),'min':np.minimum(a,b),'abs':abs(a-b)}
def scan(a,b,y):
    F=fs(a,b);names=list(F);best=(0,)
    for n1,n2 in itertools.combinations(names,2):
        for p in range(8):
            for q in range(8):
                d=(y-p*F[n1]-q*F[n2])%8
                c=np.bincount(d,minlength=8).max()
                if c>best[0]: best=(int(c),n1,p,n2,q,int(np.bincount(d,minlength=8).argmax()))
    return best
for s in range(4):
    a,b,y=D[s].T
    print('skill',s,'two-feature',scan(a,b,y),'shuffled',scan(a,b,rng.permutation(y))[0])
