rng=np.random.default_rng(2)
def conds(a,b):
    C={}
    for k in range(1,32):
        C[f'a<{k}']=a<k; C[f'b<{k}']=b<k
    for k in range(1,63): C[f'a+b<{k}']=a+b<k
    for k in range(-30,31): C[f'a-b<{k}']=a-b<k
    for m in range(2,9):
        for r in range(m):
            C[f'a%{m}=={r}']=a%m==r; C[f'b%{m}=={r}']=b%m==r
            C[f'(a+b)%{m}=={r}']=(a+b)%m==r; C[f'(a-b)%{m}=={r}']=(a-b)%m==r
    for i in range(5):
        C[f'a[{i}]']=(a>>i)&1==1; C[f'b[{i}]']=(b>>i)&1==1; C[f'x[{i}]']=((a^b)>>i)&1==1
    return C
P=[(p,q) for p in range(8) for q in range(8)]
def fit(a,b,y):
    if len(y)==0: return 0,None
    V=np.array([(y-p*a-q*b)%8 for p,q in P])
    cnt=np.array([np.bincount(v,minlength=8) for v in V])
    i=np.unravel_index(cnt.argmax(),cnt.shape)
    return int(cnt[i]),(P[i[0]],int(i[1]))
def scan(a,b,y,detail=False):
    res=[]
    for n,m in conds(a,b).items():
        if m.sum()<8 or (~m).sum()<8: continue
        c1,r1=fit(a[m],b[m],y[m]);c2,r2=fit(a[~m],b[~m],y[~m])
        res.append((c1+c2,n,r1,r2))
    res.sort(key=lambda z:-z[0])
    return res[:3]
for s in range(4):
    a,b,y=D[s].T
    print('skill',s,scan(a,b,y),'shuffled',scan(a,b,rng.permutation(y))[0][0])
